def resolve(path, cwd, links):
    # Normalize the input path
    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path

    # Split path into components
    components = path.split('/')

    # Start resolving
    current = '/'
    link_count = 0

    # Skip the first empty component (from leading '/')
    for component in components[1:]:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append the component
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if the current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            # Get the symlink target
            target = links[current]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = target
            else:
                # Relative target - relative to the directory containing the link
                link_dir = current.rsplit('/', 1)[0]
                if link_dir == '':
                    link_dir = '/'
                current = link_dir.rstrip('/') + '/' + target

            # We need to resolve the target path further
            # Recursively resolve from the current position
            result = resolve(current, cwd, links)
            if result is None:
                return None
            current = result

    # Remove trailing slash, except for '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

